def smallestSubsetDivisibleByM(nums, m):
    INF = float("inf")
    dp = [INF] * m  # dp[r]: fewest elements in a non-empty subset with sum % m == r
    for x in nums:
        new = dp[:]
        xr = x % m
        if new[xr] > 1:
            new[xr] = 1
        for r in range(m):
            if dp[r] != INF:
                t = (r + xr) % m
                if dp[r] + 1 < new[t]:
                    new[t] = dp[r] + 1
        dp = new
    return -1 if dp[0] == INF else dp[0]
